/*
 * BH1750 Light Intensity Sensor Example
 *
 * Reads ambient light level in lux and controls an LED.
 * LED brightness adjusts automatically based on light conditions.
 *
 * Wiring:
 *   BH1750 VCC -> Arduino 5V
 *   BH1750 GND -> Arduino GND
 *   BH1750 SCL -> Arduino A5 (SCL)
 *   BH1750 SDA -> Arduino A4 (SDA)
 *   LED anode  -> Arduino D9 (PWM)
 *   LED cathode -> Arduino GND
 *
 * Light Levels Reference:
 *   0 lx       = Complete darkness
 *   10-50 lx   = Dark room
 *   100-200 lx = Living room (dim)
 *   400-500 lx = Office lighting
 *   750-1000 lx = Bright indoor
 *   10000-25000 lx = Overcast day
 *   30000-100000 lx = Direct sunlight
 */

#include <Wire.h>
#include <BH1750.h>

// Create BH1750 instance
BH1750 lightSensor;

// LED pin
const int LED_PIN = 9;

// Light level thresholds (in lux)
const float DARK_THRESHOLD = 50.0;
const float DIM_THRESHOLD = 200.0;
const float BRIGHT_THRESHOLD = 1000.0;

void setup() {
  Serial.begin(115200);
  Serial.println("BH1750 Light Sensor Demo");
  Serial.println("=======================");

  // Initialize I2C and sensor
  Wire.begin();

  // Begin in continuous high-resolution mode
  if (lightSensor.begin(BH1750::CONTINUOUS_HIGH_RES_MODE)) {
    Serial.println("BH1750 initialized successfully!");
  } else {
    Serial.println("Error: BH1750 not found!");
    while (1);
  }

  // Set LED pin
  pinMode(LED_PIN, OUTPUT);

  Serial.println();
  delay(100);
}

void loop() {
  // Read light level
  float lux = lightSensor.readLightLevel();

  // Check for valid reading
  if (lux < 0) {
    Serial.println("Error reading sensor!");
    delay(1000);
    return;
  }

  // Map lux to LED brightness (0-255)
  // Inverse relationship: darker = brighter LED
  int ledBrightness;

  if (lux < DARK_THRESHOLD) {
    // Very dark - LED at full brightness
    ledBrightness = 255;
  } else if (lux < DIM_THRESHOLD) {
    // Dim lighting - LED moderately bright
    ledBrightness = map(lux, DARK_THRESHOLD, DIM_THRESHOLD, 255, 128);
  } else if (lux < BRIGHT_THRESHOLD) {
    // Normal indoor - LED dim
    ledBrightness = map(lux, DIM_THRESHOLD, BRIGHT_THRESHOLD, 128, 32);
  } else {
    // Bright daylight - LED off or very dim
    ledBrightness = map(lux, BRIGHT_THRESHOLD, 10000, 32, 0);
    ledBrightness = constrain(ledBrightness, 0, 32);
  }

  // Apply brightness
  analogWrite(LED_PIN, ledBrightness);

  // Print to Serial Monitor
  Serial.print("Light: ");
  Serial.print(lux, 1);
  Serial.print(" lx | LED: ");
  Serial.print(ledBrightness);
  Serial.print("/255 | ");

  // Print light condition
  if (lux < DARK_THRESHOLD) {
    Serial.println("DARK - LED ON full");
  } else if (lux < DIM_THRESHOLD) {
    Serial.println("DIM - LED medium");
  } else if (lux < BRIGHT_THRESHOLD) {
    Serial.println("NORMAL - LED dim");
  } else {
    Serial.println("BRIGHT - LED OFF");
  }

  // Update every 500ms
  delay(500);
}
